source('mp10_hypothesis_followup_v2/scripts/common.R');suppressPackageStartupMessages(library(fgsea))
reg<-rd('model_registry.tsv')[kind=='gsea'];sig<-rd('official_gene_sets.tsv.gz');sets<-lapply(split(sig$gene,sig$signature),unique);out<-list();ranksout<-list();map<-c(H50='M0001',H10='M0016',H05='M0031');stat<-old('model_status.tsv')
for(st in names(map))for(ma in c('Full','M20')){
 id<-map[[st]];d<-fread(file.path(OLD,'tables/de',paste0(id,'.tsv.gz')));d<-d[is.finite(signed_stat)&!gene%in%if(ma=='M20')M20 else character()];setorder(d,-signed_stat,gene);ranks<-setNames(d$signed_stat,d$gene);stopifnot(!anyDuplicated(names(ranks)));ss<-lapply(sets,setdiff,y=if(ma=='M20')M20 else character());rr<-reg[state==st&mask==ma];ss<-ss[rr$y];cov<-sapply(ss,function(g)sum(g%in%names(ranks)));valid<-ss[cov>=15&cov<=500];warnings<-character();budget<-10000
 if(length(valid)){set.seed(123);z<-withCallingHandlers(as.data.table(fgseaMultilevel(valid,ranks,minSize=15,maxSize=500,nPermSimple=budget,eps=1e-10,scoreType='std',nproc=1)),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart('muffleWarning')});if(any(!is.finite(z$pval))){budget<-100000;set.seed(123);z<-withCallingHandlers(as.data.table(fgseaMultilevel(valid,ranks,minSize=15,maxSize=500,nPermSimple=budget,eps=1e-10,scoreType='std',nproc=1)),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart('muffleWarning')})};z[,leadingEdge:=vapply(leadingEdge,paste,collapse=';',FUN.VALUE=character(1))]}else z<-data.table(pathway=character(),pval=numeric(),NES=numeric(),leadingEdge=character())
 for(i in seq_len(nrow(rr))){r<-rr[i];zz<-z[pathway==r$y];o<-data.table(status=if(nrow(zz)&&is.finite(zz$pval))'completed'else'not_evaluable',reason=if(cov[[r$y]]<15)'mapped_size_below_15'else if(cov[[r$y]]>500)'mapped_size_above_500'else if(!nrow(zz)||!is.finite(zz$pval))'nonfinite_numerical_estimate'else'',n_mapped=cov[[r$y]],n_expected=length(ss[[r$y]]),NES=if(nrow(zz))zz$NES else NA_real_,P=if(nrow(zz))zz$pval else NA_real_,leadingEdge=if(nrow(zz))zz$leadingEdge else NA_character_,nPermSimple=budget,P_at_eps_floor=if(nrow(zz))zz$pval<=1e-10 else NA,source_model=id,source_DE=file.path(OLD,'tables/de',paste0(id,'.tsv.gz')),warning=paste(unique(warnings),collapse=' | '));s<-stat[model_id==id];o[,`:=`(n_specimens=s$n_specimens,n_recorded_patient_units=s$n_recorded_patient_units,n_datasets=s$n_datasets,residual_df=s$residual_df,method='edgeR signed statistic / fgseaMultilevel')];out[[r$model_id]]<-cbind(r,o)}
 ranksout[[paste(st,ma)]]<-data.table(state=st,mask=ma,gene=names(ranks),signed_stat=as.numeric(ranks));cat('GSEA',st,ma,length(valid),'\n')
}
z<-rbindlist(out,fill=TRUE);z[,q:=p.adjust(P,'BH',n=unique(planned_n)),by=FDR_family];z[,testable_n:=sum(is.finite(P)),by=FDR_family];put(z,'gsea_model_results.tsv.gz');put(rbindlist(ranksout),'gsea_frozen_ranks.tsv.gz');tf<-rbindlist(lapply(names(map),function(s){d<-fread(file.path(OLD,'tables/de',paste0(map[[s]],'.tsv.gz')))[gene%in%c('SREBF1','SREBF2','SCAP','INSIG1','NECTIN2','PVRL2')];d[,`:=`(state=s,source_model=map[[s]],source='original whole-genome edgeR DE; original FDR unchanged')];d}));put(tf,'TF_RNA_historical_evidence.tsv');thread_audit('formal_gsea_complete')
